#!/usr/bin/env ruby

require 'digest/md5'
require 'shellwords'

BASE_CFLAGS = ENV['CFLAGS'] || "-ggdb3 -O2 -DNDEBUG -Wall -Wextra -march=native"
APPEND_CFLAGS = ENV['APPEND_CFLAGS'] || "-Iv/mini-x86-int -Imini-x86-int/base -Iinclude"
# Nicer to have compile cmdline to start with BASE_CFLAGS and cruft
# like includes later, but sometimes we need to be able to override
# these
CFLAGS = [BASE_CFLAGS, APPEND_CFLAGS].join(' ')
LDFLAGS = ENV['LDFLAGS'] || ''

REQUIRED_LIBS = "-latomic"
LIBS = [(ENV['LIBS'] || ''), REQUIRED_LIBS].join(' ')

CC = ENV['CC'] || 'cc'
CXX = ENV['CXX'] || 'c++'

# NOTE: CXXFLAGS is unorhtodox by being addition to CFLAGS
BASE_CXXFLAGS = ENV['CXXFLAGS'] || "-std=c++20 -fno-exceptions -fno-rtti"
CXXFLAGS = [BASE_CFLAGS, BASE_CXXFLAGS, APPEND_CFLAGS].join(' ')

# What is that? Well, a simple "executable model" of the source
# (subset of). Hopefully it should be more or less
# self-explanatory. Describes what gets built without getting into the
# weeds of compilation details. When this model runs with NinjaBulder
# it produces build.ninja. If you want to get the general idea where
# it came from see
# https://github.com/gperftools/gperftools-demo/blob/fc538963d604faee34d635ba82cf2d79c3cd564b/generate_builds.rb
# where single model drives several build generators.
#
# Here is one thing worth keeping in mind reading the build!  source
# below. A number of "input" arguments (like inputs: or src:) are
# automagically flattened. So it could be singular thing or (nested)
# array of things and it just works.
def build! b
  aw_backtrace = b.o(src: %w[aw-backtrace.cc backtrace-core.cc])
  aw_addrcheck = b.o(src: "aw-addrcheck.c")

  comparer = b.o(src: "backtrace-comparer.cc", cflags: %w[-DBUILD_SO -DAW_BUMP_STATS_IN_PRODUCTION])
  aw_backtrace = b.override_cflags(aw_backtrace) {|_, cflags| cflags + %w[-DAW_BUMP_STATS_IN_PRODUCTION]}

  sym_helper_bin = b.program(name: "sym_helper_bin", inputs: b.o(src: "sym-helper.cc"))

  symbolize_backtrace = [
    b.o(src: "symbolize-backtrace.cc"),
    b.objcopy(from: sym_helper_bin)]

  sim_stepper = b.o(src: %w[sim_stepper.cc base/single_stepper.cc mini-x86-int.cc performs.S].map {|s| "v/mini-x86-int/#{s}"})

  def override_visibility(b, objs)
    # return b.override_cflags objs do |name, cflags|
    #   cflags + ["-fvisibility=hidden", "-DAW_HIDDEN_VISIBILITY"]
    # end
    objs
  end

  backtrace_comparer_so = b.dot_so(name: "backtrace-comparer.so",
                                   inputs: override_visibility(b, [comparer, aw_backtrace, aw_addrcheck, symbolize_backtrace, sim_stepper]),
                                   version_script: "backtrace-comparer.so.map")

  test_signal_disable = b.program(name: "test-signal-disable", inputs: [b.o(src: "v/mini-x86-int/test-signal-disable.cc"), sim_stepper])

  def add_nopie(b, objs)
    return b.override_cflags(objs) do |name, cflags|
      cflags + %w[-fno-pie]
    end
  end

  cjm = b.program(name: "cjm",
                  inputs: add_nopie(b,
                                    [b.o(src: %w[comparer-longjmp.cc backtrace-comparer.cc]),
                                     sim_stepper, aw_backtrace, aw_addrcheck, symbolize_backtrace]),
                  libs: %w[-no-pie])

  cjm0 = b.program(name: "cjm0",
                   inputs: [b.o(src: %w[comparer-longjmp.cc], cflags: %w[-DSKIP_COMPARER -no-pie])],
                   libs: %w[-no-pie])


  [backtrace_comparer_so, sym_helper_bin, test_signal_disable,
   cjm, cjm0]
end

def better_shell_escape(str)
  return str if Shellwords.split(str) == [str]
  simple = "'#{str}'"
  return simple if Shellwords.split(simple) == [str]
  return Shellwords.escape(str)
end

class NinjaBulder
  Artifact = Struct.new(:name, :build)
  LibraryPair = Struct.new(:static, :shared)
  class LibraryPair; def name; [self.static.name, self.shared.name]; end; end
  OBJ = Struct.new(:src_name, :cflags)
  CUSTOM_OBJ = Struct.new(:name, :build)

  PRECIOUS_ENVS = %w[CC CXX CFLAGS APPEND_CFLAGS CXXFLAGS LIBS LDFLAGS NO_GENERATOR]

  OVERRIDES = begin
                vs = PRECIOUS_ENVS.map {|n| ENV[n]}
                used_pairs = PRECIOUS_ENVS.zip(vs).select {|(_, v)| v}
                used_pairs.map {|k, v| "#{k}=#{better_shell_escape v}"}.join(' ')
              end.tap {|str| str[0,0] = ' ' unless str.empty? }

  BFD_ARCH = begin # e.g. elf64-x86-64 for objcopy call
               raise unless `objdump -f /bin/cat` =~ /file format (elf.*)$/
               $1.chomp
             end

  PREAMBLE = (<<HERE)
# generated by #{__FILE__}#{OVERRIDES}. Edit there

rule CC
  command = #{CC} -c $in #{CFLAGS} ${extra_cflags} -MMD -MF $out.d -o $out
  depfile = $out.d
  deps = gcc
  description = CC	$in -> $out : ${extra_cflags}

rule CC_PIC
  command = #{CC} -c $in #{CFLAGS} -fPIC ${extra_cflags} -MMD -MF $out.d -o $out
  depfile = $out.d
  deps = gcc
  description = CC_PIC	$in -> $out : ${extra_cflags}

rule CXX
  command = #{CXX} -c $in #{CXXFLAGS} ${extra_cflags} -MMD -MF $out.d -o $out
  depfile = $out.d
  deps = gcc
  description = CXX	$in -> $out : ${extra_cflags}

rule CXX_PIC
  command = #{CXX} -c $in #{CXXFLAGS} -fPIC ${extra_cflags} -MMD -MF $out.d -o $out
  depfile = $out.d
  deps = gcc
  description = CXX_PIC	$in -> $out : ${extra_cflags}

rule AS_PIC
  command = #{CXX} -c $in #{CFLAGS} -fPIC ${extra_cflags} -MMD -MF $out.d -o $out
  depfile = $out.d
  deps = gcc
  description = S_PIC	$in -> $out : ${extra_cflags}

rule AS
  command = #{CXX} -c $in #{CFLAGS} ${extra_cflags} -MMD -MF $out.d -o $out
  depfile = $out.d
  deps = gcc
  description = S	$in -> $out : ${extra_cflags}

rule LINK_PROG
  command = #{CXX} -fno-exceptions -o $out #{LDFLAGS} $in ${link_libs} #{LIBS}

rule LINK_SO
  command = #{CXX} -shared -o $out #{LDFLAGS} $in ${link_libs} #{LIBS}

rule LINK_A
  command = rm -f $out && ar cr $out $in && ranlib $out

rule OBJCOPY
  command = objcopy -I binary -O #{BFD_ARCH} $in $out --rename-section .data=.rodata,alloc,load,readonly,data,contents

rule regenerate_build_files
  command = #{__FILE__}#{OVERRIDES}
  generator = 1

#{if ENV['NO_GENERATOR'] then '#' else '' end}build build.ninja: regenerate_build_files #{__FILE__}

HERE

  def shorten_digests(digests)
    return [] if digests.empty?

    prev, *digests = digests
    prev_l = 0
    prefixes = []
    digests.each do |d|
      l = [d.size, prev.size].min
      sz = l.times.detect do |i|
        d[0..i] != prev[0..i]
      end
      prefixes << prev[0..([prev_l, sz].max)]
      prev = d
      prev_l = sz
    end
    prefixes << prev[0..prev_l]

    prefixes
  end

  def map_build(artifact)
    if artifact.respond_to? :build
      map_build(artifact.build)
    elsif artifact.kind_of? LibraryPair
      map_build([artifact.static, artifact.shared])
    elsif artifact.kind_of?(Enumerable)
      artifact.map {|a| map_build(a)}
    elsif artifact.kind_of? String
      artifact
    else
      raise "bad type? #{artifact.pretty_print}"
    end
  end

  def dedup_and_emit!(artifacts)
    artifact_names = [artifacts].flatten.map(&:name).flatten

    statements = map_build(artifacts).flatten.uniq

    File.open("build.ninja", "w") do |f|
      f << PREAMBLE.split("\n").map(&:rstrip).join("\n") + "\n\n"

      chomped = statements.map(&:chomp)

      digests = chomped.map do |build|
        next unless build =~ /_([0-9a-f]{32})-/
        $1
      end.compact.sort.uniq

      replacements = digests.zip(shorten_digests(digests))

      chomped = chomped.map do |build|
        replacements.inject(build) do |b, (digest, replacement)|
          b.gsub(digest, replacement)
        end
      end
      f << chomped.join("\n\n")
      f.puts
      f.puts

      f.puts("default #{artifact_names.join(' ')}")
    end

    path = File.expand_path("./build.ninja")
    if OVERRIDES.empty?
      STDERR.puts "Wrote #{path}"
    else
      STDERR.puts "Wrote #{path} with overrides:#{OVERRIDES}"
    end
  end

  # TODO: enforce `in' is Array?
  def gen_build(name:, rule:, inputs:, extra_dep: [], extra_out: [], vars: {})
    extra_out = unless extra_out.empty?
                  " | #{extra_out.join(' ')}"
                else
                  ""
                end
    extra_dep = unless extra_dep.empty?
                  " | #{extra_dep.join(' ')}"
                else
                  ""
                end
    build = "build #{name}#{extra_out} : #{rule} #{[inputs].flatten.join(' ')}#{extra_dep}\n"
    vars.each do |k, v|
      next if v.empty?
      build << "  #{k} = #{v}\n"
    end
    build
  end

  def assert_strings!(strings)
    strings.each {|s| raise unless s.kind_of? String}
  end

  def o(src:, cflags: "")
    src = [src].flatten
    assert_strings! src
    src.map {|s| OBJ.new(s, cflags)}
  end

  def o_prefix(rule, cflags)
    @prefixes ||= {}
    @prefixes[[rule, cflags]] ||= if cflags.empty?
                                    "#{rule.downcase}-"
                                  else
                                    "#{rule.downcase}_#{Digest::MD5.hexdigest [cflags].flatten.join(' ')}-"
                                  end
  end

  def compile_o(src, rule, cflags)
    raise unless src.kind_of? String

    src_base = File.basename(src)
    o_basename = src_base.gsub(/\.(cc|c|cpp|cxx|S)\z/, '.o')
    src_ext = $1
    if src_ext == 'S'
      rule = rule.gsub("CC", "AS")
    elsif src_ext != 'c'
      rule = rule.gsub('CC', 'CXX')
    end

    raise if o_basename == src

    objname = ".obj/#{o_prefix(rule, cflags)}#{o_basename}"

    [objname,
     gen_build(name: objname,
               rule: rule,
               inputs: src,
               vars: {extra_cflags: [cflags].flatten.compact.join(" ")})]
  end

  def override_cflags(objs, &block)
    [objs].flatten.map do |o|
      if o.kind_of? NinjaBulder::OBJ
        o = o.dup
        o.cflags = yield(o.src_name, [o.cflags].flatten)
        o
      else
        o
      end
    end
  end

  def build_inputs(inputs, cc_rule)
    inputs.flatten.compact.map do |obj|
      if obj.kind_of? CUSTOM_OBJ
        [obj.name, obj.build]
      else
        raise "#{obj.inspect}" unless obj.kind_of? OBJ
        compile_o(obj.src_name, cc_rule, obj.cflags)
      end
    end
  end

  def do_lib(is_shared, name, inputs, libs, version)
    cc_rule = if is_shared then "CC_PIC" else "CC" end
    obj_pairs = build_inputs(inputs, cc_rule)

    link = nil # to be set below
    link_name = nil
    if is_shared
      raise "need version to be <int>:<int>:<int> got #{version}" unless version =~ /\A([0-9]+):([0-9]+):([0-9]+)\z/
      current, revision, age = $1.to_i, $2.to_i, $3.to_i
      full_name = "lib#{name}.so.#{current-age}.#{age}.#{revision}"
      plainso = full_name.gsub(/\.so\.[0-9].*\z/, ".so")
      majorso = "lib#{name}.so.#{current-age}"

      link_name = majorso
      link = gen_build(name: link_name,
                       rule: "LINK_SO",
                       inputs: obj_pairs.map(&:first),
                       vars: {soname: full_name,
                              plainso: plainso,
                              majorso: majorso,
                              link_libs: libs.join(" ")},
                       extra_out: [full_name, plainso])
    else
      link_name = "lib#{name}.a"
      link = gen_build(name: link_name,
                       rule: "LINK_A",
                       inputs: obj_pairs.map(&:first))
    end

    Artifact.new(link_name,
                 [obj_pairs.map(&:last), link])
  end

  def dot_so(name:, inputs:, libs: [], version_script: nil)
    raise "need .so suffix" unless name.end_with?(".so")
    obj_pairs = build_inputs(inputs, "CC_PIC")

    link_name = name
    link_libs = libs.join(' ')
    if version_script
      link_libs << " -Wl,--version-script=#{version_script}"
    end
    vars = {link_libs: link_libs.strip}
    link = gen_build(name: link_name,
                     rule: "LINK_SO",
                     inputs: obj_pairs.map(&:first),
                     vars: vars,
                     extra_dep: [version_script])
    Artifact.new(link_name, [obj_pairs.map(&:last), link])
  end

  def lib(name:, inputs:, libs: [], version:)
    LibraryPair.new(do_lib(false, name, inputs, libs, version),
                    do_lib(true, name, inputs, libs, version))
  end

  def static_lib(name:, inputs:, libs: [])
    do_lib(false, name, inputs, libs, nil)
  end

  def objcopy(from:)
    objname = ".obj/#{File.basename(from.name)}.o"

    build = gen_build(name: objname,
                      rule: "OBJCOPY",
                      inputs: [from.name])
    # NOTE: this is not super-clean, we need some extra dependency "pulled" automagically
    CUSTOM_OBJ.new(name: objname, build: build)
  end

  def program(name:, inputs:, is_test: false, libs: [], prefer_variant: nil)
    obj_pairs = build_inputs(inputs, "CC")
    artifact_libs, extra_libs = libs.partition {|l| l.kind_of?(Artifact) || l.kind_of?(LibraryPair)}
    variant = (prefer_variant || :shared)
    artifact_libs = artifact_libs.map {|a| if a.kind_of?(LibraryPair) then a.send(variant) else a end}
    extra_deps = artifact_libs.map(&:name)

    # maybe_rpath = " -Wl,-rpath,#{Dir.pwd}"
    maybe_rpath = ""
    # maybe_rpath = if is_test then " -Wl,-rpath,#{Dir.pwd}" end

    link = gen_build(name: name,
                     rule: "LINK_PROG",
                     inputs: obj_pairs.map(&:first),
                     extra_dep: extra_deps,
                     vars: {link_libs: (extra_deps + extra_libs).join(' ') + maybe_rpath.to_s})
    Artifact.new(name, [obj_pairs.map(&:last), link])
  end

  class B
    def initialize(parent)
      @parent = parent
    end
    def lib(**args); @parent.lib(**args); end
    def static_lib(**args); @parent.static_lib(**args); end
    def o(**args); @parent.o(**args); end
    def program(**args); @parent.program(**args); end
    def dot_so(**args); @parent.dot_so(**args); end
    def objcopy(**args); @parent.objcopy(**args); end
    def override_cflags(objs, &block); @parent.override_cflags(objs, &block); end
  end

  def build!
    b = NinjaBulder::B.new(self)
    artifacts = yield self
    dedup_and_emit! artifacts
  end
end

run_ninja = if ARGV[0] == 'ninja'
              ARGV.shift
              true
            end

unless ARGV.empty?
  overrides = {}
  re = /\A(#{NinjaBulder::PRECIOUS_ENVS.map {|e| Regexp.quote e}.join('|')})=(.*)/ #/
  ARGV.each do |arg|
    unless arg =~ re
      puts "I only accept ENV overrides likes this #{re.inspect}. Got: #{arg.inspect}"
      exit 1
    end
    overrides[$1] = $2
  end
  want_rexec = false
  overrides.each_pair do |k, v|
    next unless ENV[k] != v
    ENV[k] = v
    want_rexec = true
  end
  # if at least one override doesn't match environment variables,
  # re-exec with updated environment
  if want_rexec
    require 'rbconfig'
    maybe_build = if run_ninja then %w[ninja] else [] end
    Kernel.exec(RbConfig.ruby, $PROGRAM_NAME, *(maybe_build + ARGV))
    raise
  end
end

skip_regen = false

if run_ninja
  bf = "build.ninja"
  if File.file?(bf)
    first_line = File.open(bf, "r") { |f| f.readline}.chomp
    if first_line == NinjaBulder::PREAMBLE.split("\n", 2).first
      skip_regen = true
    end
  end
  # NOTE, ninja will regenerate if genbuild.rb is newer
end

unless skip_regen
  NinjaBulder.new.build! do |b|
    build! b
  end
end

if run_ninja
  exec "ninja -v"
end
